gold.schema_ddl:
CREATE TABLE magazzini (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    indirizzo TEXT,
    capacita_massima_kg DECIMAL(10, 2) CHECK (capacita_massima_kg >= 0)
);

CREATE TABLE corsie (
    id SERIAL PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    nome TEXT NOT NULL,
    lunghezza_metri DECIMAL(10, 2) CHECK (lunghezza_metri > 0)
);

CREATE TABLE colli (
    id SERIAL PRIMARY KEY,
    corsia_id INT NOT NULL REFERENCES corsie(id),
    peso_kg DECIMAL(10, 2) CHECK (peso_kg >= 0),
    descrizione TEXT,
    data_ingresso TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
